function demoMain(idx,label){
  var mods=[["a->b->c",3],["x->y",2],["m->n->o->p",4]];
  var m=mods[idx%mods.length];
  return "["+label+"] diagram: "+m[0]+" ("+m[1]+" nodes, SVG rendered)";
}

